export type HarthmereNamedNpc = (typeof HARTHMERE_NAMED_NPCS)[number];

export const HARTHMERE_NPC_ANIMAL_WEAPON_POLICY = {
  version: "harthmere-animal-no-weapon-policy",
  animalKindMustHaveNoWeapons: true,
  animalAssetPrefixes: ["animal_"] as const,
} as const;

export function harthmereNamedNpcActorAsset(npc: HarthmereNamedNpc): string {
  return npc.spawn.asset;
}

export function harthmereNamedNpcById(id: string): HarthmereNamedNpc | undefined {
  return HARTHMERE_NAMED_NPCS.find((npc) => npc.id === id);
}

export function harthmereNamedNpcRouteForHour(npc: HarthmereNamedNpc, hour: number) {
  const entries = npc.route.schedule;
  // `entries` is a readonly tuple where each element has a unique literal
  // hour type. Widen `current` to the union so reassignment in the loop is
  // accepted by TS while keeping the runtime semantics identical.
  let current: typeof entries[number] = entries[0];
  for (const entry of entries) {
    if (hour >= entry.hour) current = entry;
  }
  return current;
}

export function harthmereNamedNpcIsGuard(npc: HarthmereNamedNpc): boolean {
  return npc.route.routeStyle === "guard_patrol" || npc.role === "guard";
}

