export const HARTHMERE_ALL_NPCS = [
  ...HARTHMERE_NAMED_NPCS,
  ...HARTHMERE_REMAINING_NPCS,
] as const;

export type HarthmereRemainingNpc = (typeof HARTHMERE_REMAINING_NPCS)[number];
export type HarthmereAnyNpc = (typeof HARTHMERE_ALL_NPCS)[number];

export const HARTHMERE_REMAINING_NPC_COVERAGE_POLICY = {
  version: "harthmere-remaining-npc-coverage",
  v44NamedCount: 44,
  v45RemainingCount: HARTHMERE_REMAINING_NPCS.length,
  includesAmbientPopulation: true,
  includesQuestOnlyNamedPeople: true,
  includesWildlifeAndMonsterFamilies: true,
  animalKindMustHaveNoWeapons: true,
  guardRolesMustHaveWeapons: true,
  everyNpcMustHaveHomeRouteStatsInventoryAndText: true,
} as const;

export function harthmereRemainingNpcActorAsset(npc: HarthmereRemainingNpc): string {
  return npc.spawn.asset;
}

export function harthmereRemainingNpcById(id: string): HarthmereRemainingNpc | undefined {
  return HARTHMERE_REMAINING_NPCS.find((npc) => npc.id === id);
}
